import sqlite3
import json
import os
import sys
import datetime
import argparse

DB_FILE = "timebook.db"

def _ensure_db():
    if not os.path.exists(DB_FILE):
        conn = sqlite3.connect(DB_FILE)
        conn.execute(
            "CREATE TABLE events (id TEXT PRIMARY KEY, project TEXT, start TEXT, end TEXT)"
        )
        conn.commit()
        conn.close()

def _parse_iso(s):
    try:
        return datetime.datetime.fromisoformat(s)
    except Exception:
        raise ValueError(f"invalid ISO time: {s!r}")

def _to_utc(dt):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=datetime.timezone.utc)
    return dt.astimezone(datetime.timezone.utc)

def _to_seconds(dt):
    return int((dt - datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)).total_seconds())

def _add(args):
    _ensure_db()
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    try:
        id = args.id.strip()
        project = args.project.strip()
        start_str = args.start.strip()
        end_str = args.end.strip()
        if not id or not project or not start_str or not end_str:
            raise ValueError("id, project, start, and end must be nonempty")
        start = _parse_iso(start_str)
        end = _parse_iso(end_str)
        if end <= start:
            raise ValueError("end must be after start")
        cur.execute(
            "SELECT id, project, start, end FROM events WHERE id = ?", (id,)
        )
        row = cur.fetchone()
        if row:
            existing_id, existing_project, existing_start, existing_end = row
            if existing_id != id:
                raise ValueError(f"duplicate id {id!r}")
            if existing_project != project:
                raise ValueError(f"duplicate project {project!r} for id {id!r}")
            existing_start = _to_utc(existing_start)
            existing_end = _to_utc(existing_end)
            if existing_start == start and existing_end == end:
                raise ValueError(f"duplicate interval {id!r}")
            raise ValueError(f"conflicting interval {id!r}")
        cur.execute(
            "INSERT INTO events VALUES (?, ?, ?, ?)",
            (id, project, start, end),
        )
        conn.commit()
        return {"inserted": 1, "duplicates": 0}
    except Exception as e:
        conn.rollback()
        raise e
    finally:
        conn.close()

def _import(args):
    _ensure_db()
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    try:
        data = json.loads(args.input)
        if not isinstance(data, list):
            raise ValueError("input must be a JSON array")
        added = 0
        duplicates = 0
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("each event must be a JSON object")
            id = item.get("id")
            project = item.get("project")
            start = item.get("start")
            end = item.get("end")
            if not all([id, project, start, end]):
                raise ValueError("each event must have id, project, start, end")
            try:
                _add({"id": id, "project": project, "start": start, "end": end})
                added += 1
            except ValueError as e:
                duplicates += 1
        conn.commit()
        return {"inserted": added, "duplicates": duplicates}
    except Exception as e:
        conn.rollback()
        raise e
    finally:
        conn.close()

def _stats(args):
    _ensure_db()
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    try:
        from_dt = _parse_iso(args.from_date)
        to_dt = _parse_iso(args.to_date)
        if to_dt <= from_dt:
            raise ValueError("to must be after from")
        cur.execute(
            "SELECT project, start, end FROM events WHERE start >= ? AND start < ? ORDER BY project, start",
            (from_dt, to_dt),
        )
        rows = cur.fetchall()
        if not rows:
            return {"days": [], "total_seconds": 0}
        days = {}
        total = 0
        for project, start, end in rows:
            day = start.date()
            total += int((end - start).total_seconds())
            days.setdefault(day, {})
            days[day][project] = days[day].get(project, 0) + int((end - start).total_seconds())
        sorted_days = sorted(days.keys())
        result = {"days": [], "total_seconds": total}
        for day in sorted_days:
            day_data = {"projects": {}, "total_seconds": 0}
            for proj, sec in days[day].items():
                day_data["projects"][proj] = sec
                day_data["total_seconds"] += sec
            result["days"].append(day_data)
        return result
    finally:
        conn.close()

def main():
