    sub = parser.add_subparsers(dest="cmd")
    add = sub.add_parser("add")
    add.add_argument("id")
    add.add_argument("project")
    add.add_argument("start")
    add.add_argument("end")
    import_cmd = sub.add_parser("import")
    import_cmd.add_argument("input")
